PRAGMA foreign_keys=ON;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,root_path TEXT NOT NULL DEFAULT '.' CHECK(root_path='.'),current_asset_id TEXT,current_conversation_id TEXT,workspace_mode TEXT NOT NULL DEFAULT 'empty',workspace_state_json TEXT NOT NULL DEFAULT '{}',schema_version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE assets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,asset_family_id TEXT NOT NULL,parent_asset_id TEXT REFERENCES assets(id) ON DELETE RESTRICT,asset_type TEXT NOT NULL CHECK(asset_type IN ('source_image','generated_image','prompt','analysis','annotation','crop','multiview','glb','fbx','texture','preview','export')),asset_group TEXT CHECK(asset_group IS NULL OR asset_group IN ('input_images','generated_images','split_elements','multiview_and_crops','models','exports')),name TEXT NOT NULL,version_no INTEGER NOT NULL CHECK(version_no>0),relative_path TEXT NOT NULL,thumbnail_asset_id TEXT REFERENCES assets(id) ON DELETE SET NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),sha256 TEXT NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',provenance_json TEXT NOT NULL DEFAULT '{}',is_current INTEGER NOT NULL DEFAULT 0 CHECK(is_current IN(0,1)),is_hidden INTEGER NOT NULL DEFAULT 0 CHECK(is_hidden IN(0,1)),trashed_at TEXT,original_relative_path TEXT,created_at TEXT NOT NULL,UNIQUE(project_id,asset_family_id,version_no),UNIQUE(project_id,relative_path));
CREATE UNIQUE INDEX ux_assets_current_project ON assets(project_id) WHERE is_current=1 AND trashed_at IS NULL;
CREATE TABLE asset_links(from_asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,to_asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,relation_type TEXT NOT NULL CHECK(relation_type IN ('input','content','style','prompt','derived_from','source','target','result','preview_of','export_of')),PRIMARY KEY(from_asset_id,to_asset_id,relation_type));
CREATE TABLE selections(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,selection_type TEXT NOT NULL CHECK(selection_type IN ('rect','multi_rect')),geometry_json TEXT NOT NULL,label TEXT NOT NULL,confidence REAL,source TEXT NOT NULL CHECK(source IN ('user','agent')),status TEXT NOT NULL CHECK(status IN ('draft','edited','confirmed')),confirmed_by_user INTEGER NOT NULL DEFAULT 0 CHECK(confirmed_by_user IN(0,1)),revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE asset_decisions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,asset_id TEXT REFERENCES assets(id) ON DELETE RESTRICT,previous_asset_id TEXT REFERENCES assets(id) ON DELETE RESTRICT,decision_source TEXT NOT NULL CHECK(decision_source IN ('user','agent','import','system')),run_id TEXT,reason TEXT,created_at TEXT NOT NULL);
CREATE TABLE event_counters(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE RESTRICT,next_sequence_no INTEGER NOT NULL CHECK(next_sequence_no>0));
CREATE TABLE events(event_id TEXT PRIMARY KEY,event_type TEXT NOT NULL,event_version INTEGER NOT NULL DEFAULT 1,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,conversation_id TEXT,run_id TEXT,entity_id TEXT,sequence_no INTEGER NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,sequence_no));
CREATE TABLE event_consumers(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,consumer_id TEXT NOT NULL,last_sequence_no INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,PRIMARY KEY(project_id,consumer_id));
CREATE TABLE tool_calls(id TEXT PRIMARY KEY,run_id TEXT,round_index INTEGER NOT NULL DEFAULT 0,tool_name TEXT NOT NULL,tool_version TEXT NOT NULL,arguments_json TEXT NOT NULL,arguments_hash TEXT NOT NULL,idempotency_key TEXT NOT NULL,provider_profile TEXT,risk_level TEXT NOT NULL CHECK(risk_level IN('read_only','local_reversible','external','external_paid','destructive')),status TEXT NOT NULL CHECK(status IN('proposed','approved','running','queued','unknown_submission','succeeded','failed','cancelled')),result_json TEXT,error_json TEXT,duration_ms INTEGER CHECK(duration_ms IS NULL OR duration_ms>=0),started_at TEXT,finished_at TEXT);
CREATE TABLE tool_call_assets(tool_call_id TEXT NOT NULL REFERENCES tool_calls(id) ON DELETE RESTRICT,asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,direction TEXT NOT NULL CHECK(direction IN('input','output')),role TEXT NOT NULL,PRIMARY KEY(tool_call_id,asset_id,direction,role));
CREATE TABLE tool_idempotency(idempotency_key TEXT PRIMARY KEY,tool_name TEXT NOT NULL,tool_version TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('reserved','running','queued','unknown_submission','succeeded','failed_retryable','failed_terminal')),owner_tool_call_id TEXT NOT NULL REFERENCES tool_calls(id) ON DELETE RESTRICT,job_id TEXT,result_json TEXT,updated_at TEXT NOT NULL);
CREATE TABLE project_settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE operations(id TEXT PRIMARY KEY,kind TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('prepared','file_written','db_committed','completed','compensating','failed')),idempotency_key TEXT NOT NULL UNIQUE,payload_json TEXT NOT NULL,recovery_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TRIGGER asset_links_same_project BEFORE INSERT ON asset_links WHEN (SELECT project_id FROM assets WHERE id=NEW.from_asset_id)!=(SELECT project_id FROM assets WHERE id=NEW.to_asset_id) BEGIN SELECT RAISE(ABORT,'cross_project_asset_link'); END;
CREATE TRIGGER selections_same_project_insert BEFORE INSERT ON selections WHEN NEW.project_id!=(SELECT project_id FROM assets WHERE id=NEW.asset_id) BEGIN SELECT RAISE(ABORT,'cross_project_selection'); END;
CREATE TRIGGER selections_same_project_update BEFORE UPDATE OF asset_id,project_id ON selections WHEN NEW.project_id!=(SELECT project_id FROM assets WHERE id=NEW.asset_id) BEGIN SELECT RAISE(ABORT,'cross_project_selection'); END;
CREATE TRIGGER asset_thumbnail_same_project BEFORE UPDATE OF thumbnail_asset_id ON assets WHEN NEW.thumbnail_asset_id IS NOT NULL AND NEW.project_id!=(SELECT project_id FROM assets WHERE id=NEW.thumbnail_asset_id) BEGIN SELECT RAISE(ABORT,'cross_project_thumbnail'); END;
CREATE TRIGGER asset_decision_same_project BEFORE INSERT ON asset_decisions WHEN (NEW.asset_id IS NOT NULL AND NEW.project_id!=(SELECT project_id FROM assets WHERE id=NEW.asset_id)) OR (NEW.previous_asset_id IS NOT NULL AND NEW.project_id!=(SELECT project_id FROM assets WHERE id=NEW.previous_asset_id)) BEGIN SELECT RAISE(ABORT,'cross_project_asset_decision'); END;
CREATE TRIGGER project_current_asset_guard BEFORE UPDATE OF current_asset_id ON projects WHEN NEW.current_asset_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM assets WHERE id=NEW.current_asset_id AND project_id=NEW.id AND trashed_at IS NULL) BEGIN SELECT RAISE(ABORT,'invalid_current_asset'); END;
CREATE INDEX ix_assets_project_type ON assets(project_id,asset_type,is_hidden,trashed_at,created_at);
CREATE INDEX ix_assets_family ON assets(project_id,asset_family_id,version_no);
CREATE INDEX ix_selections_asset ON selections(project_id,asset_id,status);
CREATE INDEX ix_events_replay ON events(project_id,sequence_no);
CREATE INDEX ix_tool_calls_run ON tool_calls(run_id,round_index);
